from typing import List, Dict, Any, Optional

# Helper for bounding boxes and geometry
def create_bounding_box_polygon(lat: float, lon: float, delta_deg: float = 0.02) -> Dict[str, Any]:
    return {
        "type": "Polygon",
        "coordinates": [[
            [round(lon - delta_deg, 5), round(lat - delta_deg, 5)],
            [round(lon + delta_deg, 5), round(lat - delta_deg, 5)],
            [round(lon + delta_deg, 5), round(lat + delta_deg, 5)],
            [round(lon - delta_deg, 5), round(lat + delta_deg, 5)],
            [round(lon - delta_deg, 5), round(lat - delta_deg, 5)],
        ]]
    }

def compute_bbox_bounds(lat: float, lon: float, delta_deg: float = 0.02) -> List[List[float]]:
    return [
        [round(lat - delta_deg, 5), round(lon - delta_deg, 5)],
        [round(lat + delta_deg, 5), round(lon + delta_deg, 5)]
    ]

